-- password is set out of band (ALTER ROLE acard_app PASSWORD ...), never committed
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'acard_app') THEN CREATE ROLE acard_app LOGIN; END IF; END $$;
ALTER ROLE acard_app SET search_path = acard;
GRANT USAGE ON SCHEMA acard TO acard_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA acard TO acard_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA acard TO acard_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA acard GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO acard_app;
DROP POLICY IF EXISTS acard_app_all ON acard.page_fts_state; CREATE POLICY acard_app_all ON acard.page_fts_state TO acard_app USING (true) WITH CHECK (true);
